// 同场所、公职epoch、候选身份和游标逐次重验；报价失败仅显示原明确原因，不生成草案。
#include "supply_policy_view.hpp"
#include "supply_policy_internal.hpp"
#include "supply_policy_codec.hpp"
#include "resident/domains/organization/organization_model.hpp"
namespace hanmo::resident {
namespace {
LocalEconomyAuthorityKey key(const ActingAuthority& a){return {a.organization_id,a.office_id,a.authority_epoch,a.actor_id};}
Outcome<std::optional<PoliticalResponsibilityExecution>> current_source(const EconomicSupplyPolicyContext& x,const PoliticalTakeoverRead& read,const StableId& source){return read.find_political_responsibility_for_execution({PoliticalResponsibilityKind::supply_source,source,{},{}},x.ledger.common.state().identity);}
}
Outcome<EconomicSupplyPolicyIndex> build_economic_supply_policy_index(const EconomicSupplyPolicyContext& x,const OrganizationState& state,const OrganizationRead& organizations,const PoliticalTakeoverRead& political){
 auto valid=validate_economic_supply_policies(x);if(!valid.ok)return {false,{},valid.error};if(x.ledger.phase)return {false,{},common_failure("EconomicSupplyPageRequiresCommittedClock").error};const auto& c=x.ledger.common;EconomicSupplyPolicyIndex out;out.identity=c.state().identity;out.observer_actor_id=c.state().metadata.player_actor_id;const auto* actor=c.actor(out.observer_actor_id);const auto location=c.resolved_location(out.observer_actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!actor||!actor->alive||!here)return {true,std::move(out),{}};out.place_id=here->place_id;
 for(const auto& row:state.offices.rows()){const auto& office=row.second;if((!office.holder_actor_id||*office.holder_actor_id!=actor->id)&&(!office.deputy_actor_id||*office.deputy_actor_id!=actor->id))continue;ActingAuthority a{office.organization_id,office.id,office.epoch,actor->id};if(!organizations.authorize(a,"inspect_local_economy",{ScopeRef::Kind::site,out.place_id},0).ok)continue;out.authorities.push_back(a);auto& sources=out.sources[key(a)];
  for(const auto& definition:x.ledger.catalog.policies.rows()){const auto& d=definition.second;const auto* source=x.ledger.economy_catalog.supply_sources.find(d.original_source_key);if(d.organization_id!=a.organization_id||source->site_id!=out.place_id)continue;auto captured=current_source(x,political,d.original_source_key);if(!captured.ok)return {false,{},captured.error};if(!captured.value||captured.value->registration.successor_organization_id!=a.organization_id||captured.value->registration.site_id!=out.place_id)continue;sources.push_back({true,d.id,captured.value->registration_fact_id});}
  for(const auto& issued:x.ledger.state.policies.rows())if(issued.second.policy.organization_id==a.organization_id&&issued.second.policy.site_id==out.place_id)sources.push_back({false,issued.first,issued.second.registration_fact_id});
 }
 return {true,std::move(out),{}};
}
Outcome<EconomicSupplyPolicyPage> query_economic_supply_policies(const EconomicSupplyPolicyContext& x,const OrganizationRead& organizations,const PoliticalTakeoverRead& political,const EconomicSupplyPolicyIndex& index,const LocalEconomyQuery& query){
 using namespace economic_supply_detail;const auto fail=[](const StableId& code)->Outcome<EconomicSupplyPolicyPage>{return {false,{},common_failure(code).error};};if(x.ledger.phase)return fail("EconomicSupplyPageRequiresCommittedClock");const auto& c=x.ledger.common;if(query.observer_actor_id.empty()||query.observer_actor_id!=c.state().metadata.player_actor_id)return fail("LocalEconomyObserverRequired");const auto* actor=c.actor(query.observer_actor_id);auto location=c.resolved_location(query.observer_actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!actor||!actor->alive||!here||here->place_id!=query.place_id)return fail("LocalEconomyPlaceNotObservable");if(!identity(index.identity,c.state().identity)||index.observer_actor_id!=query.observer_actor_id||index.place_id!=query.place_id)return fail("StaleEconomicSupplyIndex");
 const std::vector<EconomicSupplyViewSource> empty;const auto* sources=&empty;if(query.authority){const auto& a=*query.authority;if(a.actor_id!=query.observer_actor_id)return fail("LocalEconomyAuthorityActorMismatch");auto permission=organizations.authorize(a,"inspect_local_economy",{ScopeRef::Kind::site,query.place_id},0);if(!permission.ok)return {false,{},permission.error};auto found=index.sources.find(key(a));if(found==index.sources.end())return fail("StaleEconomicSupplyIndex");sources=&found->second;}
 Integer offset=0;if(query.cursor){const auto& cursor=*query.cursor;if(!identity(cursor.identity,c.state().identity)||cursor.observer_actor_id!=query.observer_actor_id||cursor.place_id!=query.place_id||bool(cursor.authority)!=bool(query.authority)||(cursor.authority&&key(*cursor.authority)!=key(*query.authority)))return fail("StaleLocalEconomyCursor");offset=cursor.offset;}if(offset<0||offset>static_cast<Integer>(sources->size()))return fail("InvalidLocalEconomyCursor");EconomicSupplyPolicyPage result;auto& page=result.base;page.identity=c.state().identity;page.observer_actor_id=query.observer_actor_id;page.place_id=query.place_id;page.cursor=offset;page.authorities.assign(index.authorities.begin(),index.authorities.end());
 while(offset<static_cast<Integer>(sources->size())&&result.rows.size()<static_cast<std::size_t>(local_economy_page_limit)){const auto ref=(*sources)[offset++];++page.scanned;EconomicSupplyPolicyViewRow row;row.id=ref.id;row.registration_fact_id=ref.registration_fact_id;
  if(ref.authored){const auto* d=x.ledger.catalog.policies.find(ref.id);const auto* source=d?x.ledger.economy_catalog.supply_sources.find(d->original_source_key):nullptr;if(!d||!source||d->organization_id!=query.authority->organization_id||source->site_id!=query.place_id)return fail("StaleEconomicSupplyIndex");auto capture=current_source(x,political,d->original_source_key);if(!capture.ok)return {false,{},capture.error};if(!capture.value||capture.value->registration_fact_id!=ref.registration_fact_id)return fail("StaleEconomicSupplyIndex");auto policy=freeze_economic_supply_need_policy(*d,*source,"economic_supply_policy:quote");if(!policy.ok)return {false,{},policy.error};row.policy=policy.value;row.original_source_key=d->original_source_key;row.target_amount=d->target_amount;row.maximum_contract_commitment=quote_need_policy_commitment(row.policy).value.total;row.status="authored_terms";IssueEconomicSupplyPolicyCommand command{*query.authority,ref.registration_fact_id,d->id};auto quote=preview_economic_supply_policy(x,query.observer_actor_id,command);if(quote.ok){row.issue_command=command;row.effective_tick=quote.value.proposed.earliest_effective_tick;row.through_tick=quote.value.proposed.through_tick;}else row.unavailable_code=quote.error.original.code;
  }else{const auto* r=x.ledger.state.policies.find(ref.id);if(!r||r->policy.organization_id!=query.authority->organization_id||r->policy.site_id!=query.place_id||r->registration_fact_id!=ref.registration_fact_id)return fail("StaleEconomicSupplyIndex");auto current=EconomicSupplyPolicyAccess(x).economic_supply_policy(ref.id);if(!current.ok)return {false,{},current.error};if(!current.value)return fail("StaleEconomicSupplyIndex");row.policy=r->policy;row.original_source_key=r->original_source_key;row.target_amount=r->target_amount;row.maximum_contract_commitment=current.value->issued.maximum_contract_commitment;row.issued_tick=r->issued_tick;row.effective_tick=current.value->effective_tick;row.through_tick=r->through_tick;row.status=current.value->new_contracts_allowed?"approved_active":"paused";row.unavailable_code=current.value->unavailable_code;row.last_observation_fact_id=current.value->last_observation_fact_id;if(const auto* observed=x.ledger.state.observations.find(row.last_observation_fact_id))row.observed_amount=observed->observation.observation.physical_amount;}
  result.rows.push_back(std::move(row));
 }
 if(offset<static_cast<Integer>(sources->size()))page.next_cursor=LocalEconomyCursor{page.identity,query.observer_actor_id,query.place_id,query.authority,offset};return {true,std::move(result),{}};
}
BoundaryValue encode_economic_supply_policy_page(const EconomicSupplyPolicyPage& page){using V=BoundaryValue;auto out=encode_local_economy_page(page.base);V::Array rows;for(const auto& r:page.rows)rows.push_back(boundary::obj({{"id",V{r.id}},{"registration_fact_id",V{r.registration_fact_id}},{"original_source_key",V{r.original_source_key}},{"status",V{r.status}},{"unavailable_code",V{r.unavailable_code}},{"policy",dynamic_economy_codec::encode(r.policy)},{"target_amount",V{r.target_amount}},{"maximum_contract_commitment",V{r.maximum_contract_commitment}},{"issued_tick",V{r.issued_tick}},{"effective_tick",V{r.effective_tick}},{"through_tick",V{r.through_tick}},{"last_observation_fact_id",V{r.last_observation_fact_id}},{"observed_amount",r.observed_amount?V{*r.observed_amount}:V{}},{"issue_command",r.issue_command?encode_issue_economic_supply_policy(*r.issue_command):V{}}}));*out.find("rows")=V{std::move(rows)};return out;}
}
